const RC=META.parts.length+1, QZ=RC+1, LS=RC+2, OUT=RC+3;

/* ---------- drawing helpers for this lesson (prefixed VL_ so they never clash with engine globals) ---------- */
const VL_F='font-family="Nunito Sans, sans-serif"';
const VL_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${VL_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}">${t}</text>`;
const VL_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const VL_R=(x,y,w,h,fill,st='none',sw=2,r=0,ex='')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${fill}" stroke="${st}" stroke-width="${sw}" ${ex}/>`;
const VL_box=(x,y,w,h,o={})=>VL_R(x,y,w,h,o.fill||'#FFFFFF',o.st||'#CED4DA',o.sw||2,o.r??14);
const VL_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return VL_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const VL_s=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
/* silicon colours: p-type sand, n-type blue, n+ deep blue, p+ deep orange, poly purple, oxide grey, metal dark grey, resist yellow */
const VL_PS='#FFF0DB',VL_PSs='#E8A04F',VL_NW='#DCE6FF',VL_NWs='#4263EB',VL_NP='#3B5BDB',VL_PP='#E8590C',VL_PO='#AE3EC9',VL_OX='#ADB5BD',VL_ME='#495057',VL_RE='#FFD43B',VL_REs='#F08C00';
const VL_sub=(x,y,w,h)=>VL_R(x,y,w,h,VL_PS,VL_PSs,2);
const VL_well=(x,y,w,h)=>VL_R(x,y,w,h,VL_NW,VL_NWs,2.5,14);
const VL_dop=(x,y,w,h,col,lab,fs=22)=>VL_R(x,y,w,h,col,'none',0,4)+VL_T(x+w/2,y+h/2+fs*.36,lab,{fs,fw:800,a:'middle',fill:'#FFFFFF'});
const VL_gate=(x,y,w,h=30,lab='')=>VL_R(x,y-6,w,6,VL_OX)+VL_R(x,y-6-h,w,h,VL_PO,'none',0,4)+(lab?VL_T(x+w/2,y-6-h/2+8,lab,{fs:22,fw:800,a:'middle',fill:'#FFFFFF'}):'');
const VL_dn=(xs,y1,y2,col=VL_NWs,w=3)=>xs.map(x=>VL_arrow(x,y1,x,y2,col,w)).join('');
const VL_heat=(xs,y)=>xs.map(x=>`<path d="M${x} ${y} q8 -9 0 -18 q-8 -9 0 -18" fill="none" stroke="${ORG}" stroke-width="4" stroke-linecap="round"/>`).join('');
const VL_hide=(t,svg)=>`<g class="hideAt" style="--d:${(+t).toFixed(2)}s">${svg}</g>`;
