function EXTRA(R,ICON){
 /* hook: a stack of ten mask plates over a wafer of dies */
 ICON.vlStack=(x,y)=>{let s=`<g transform="translate(${x-200} ${y-130})">`;for(let i=0;i<10;i++){const yy=20+i*20,col=i<5?BLU:ORG;s+=`<path d="M${60+i*4} ${yy} H${330+i*4} L${300+i*4} ${yy+26} H${30+i*4} Z" fill="${i<5?'#DCE6FF':'#FFE8CC'}" stroke="${col}" stroke-width="2.5"/>`}
  s+=`<path d="M96 200 H366 L336 226 H66 Z" fill="#FFFFFF" stroke="${INK}" stroke-width="3"/>`+[0,1,2,3].map(j=>`<rect x="${110+j*56}" y="206" width="30" height="14" fill="${INK}"/>`).join('')+VL_T(200,262,'ten masks, in order',{fs:28,fw:800,a:'middle',fill:INK})+'</g>';return s};
 ICON.vlWafer=(x,y)=>{let d='';for(let i=-5;i<5;i++)for(let j=-5;j<5;j++){const cx=x+i*24+12,cy=y+j*24+12;if(Math.hypot(cx-x+(i<0?-10:10),cy-y+(j<0?-10:10))<100)d+=`<rect x="${x+i*24+2}" y="${y+j*24+2}" width="20" height="20" rx="2" fill="${(i*7+j*3)%9===0?'#FFC9C9':'#D3F9D8'}" stroke="${GRN}" stroke-width="1"/>`}
  return `<circle cx="${x}" cy="${y}" r="112" fill="#E9ECEF" stroke="#868E96" stroke-width="4"/>${d}`};
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.vlFlow=(x,y)=>{let s=`<g transform="translate(${x-210} ${y-165})">`+VL_T(0,26,'front end',{fs:24,fw:800,fill:BLU})+VL_T(0,176,'back end',{fs:24,fw:800,fill:ORG});
  for(let i=0;i<5;i++){s+=VL_box(i*84,44,72,72,{fill:'#DCE6FF',st:BLU,sw:3,r:10})+VL_T(i*84+36,92,String(i+1),{fs:30,fw:800,a:'middle',fill:BLU});s+=VL_box(i*84,194,72,72,{fill:'#FFE8CC',st:ORG,sw:3,r:10})+VL_T(i*84+36,242,String(i+6),{fs:30,fw:800,a:'middle',fill:ORG})}
  s+=VL_R(160,184,160,92,'none',GRN,3,14,'stroke-dasharray="8 6"')+VL_T(240,312,'via + metal 2: drop both',{fs:24,fw:800,a:'middle',fill:GRN});return s+'</g>'};
 ICON.vlWells=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${VL_sub(0,120,420,170)}${VL_well(14,120,200,120)}${VL_dop(30,120,50,32,VL_PP,'p+')}${VL_dop(140,120,50,32,VL_PP,'p+')}${VL_gate(80,120,60,34)}${VL_dop(240,120,50,32,VL_NP,'n+')}${VL_dop(350,120,50,32,VL_NP,'n+')}${VL_gate(290,120,60,34)}${VL_T(110,40,'PMOS',{fs:30,fw:800,a:'middle',fill:BLU})}${VL_T(320,40,'NMOS',{fs:30,fw:800,a:'middle',fill:GRN})}${VL_T(114,222,'n-well',{fs:26,fw:800,a:'middle',fill:VL_NWs})}${VL_T(410,278,'p-substrate',{fs:24,a:'end',fill:'#5C6577'})}</g>`;
 ICON.vlNums=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${[['61 %','yield, 0.5 cm² die',ORG,0],['×10','γ for 100 × doping',BLU,112],['2.5','Wₚ/Wₙ for μₙ/μₚ',GRN,224]].map(([n,t,col,yy])=>VL_box(0,yy,420,98,{fill:'#FFFFFF',st:col,sw:3,r:14})+VL_T(24,yy+66,n,{fs:48,fw:800,fill:col})+VL_T(160,yy+60,t,{fs:24,fw:700,fill:'#18213A'})).join('')}</g>`;
}
